/*
 * The board format (`board@1`): a PM agent writes `<name>.board.json` to lay out maquette and HTML mock-ups left to right, with arrows for
 * the maquette's goto links and sticky notes beside them. It is plain data that names other workspace files (paths relative to the board's
 * folder); nothing it names is embedded or run here. The board file is the only authority: a canvas is a projection of it, and people's
 * frame moves and notes come back through `applyCanvasEdits`, never as a canvas store. The format is documented in registry/README.md
 * ("Board format"). Model output is untrusted: `parseBoard` is strict and reports every problem as an issue, and never throws.
 */
import { linksOf, parseMaquette } from '../maquette-viewer/maquette';
import type { Maquette } from '../maquette-viewer/maquette';

/** The format this module reads and writes. A higher `board@N` is reported as `newer`, not read. */
export const BOARD_FORMAT = 'board@1';
export const BOARD_FORMAT_VERSION = 1;

export type BoardDevice = 'phone' | 'desktop';

/** One thing on the board: a maquette (one frame per screen), an HTML mock-up (one frame) or a sticky note. */
export type BoardItem =
  | { readonly id: string; readonly maquette: string; readonly title?: string }
  | { readonly id: string; readonly html: string; readonly title?: string; readonly device: BoardDevice; readonly width?: number; readonly height?: number }
  | { readonly id: string; readonly note: string; readonly near?: string };

/** An arrow between two frames (`<item>/<screen>` for a maquette screen, the item id for an HTML frame). */
export interface BoardLink { readonly from: string; readonly to: string; readonly label?: string }
export interface BoardPoint { readonly x: number; readonly y: number }

export interface Board {
  readonly format: typeof BOARD_FORMAT;
  readonly title: string;
  readonly items: readonly BoardItem[];
  readonly links: readonly BoardLink[];
  /** Where people put frames and notes: frame or note id to its top-left corner. An id absent here gets the automatic layout. */
  readonly layout: Readonly<Record<string, BoardPoint>>;
}

/** A problem at a JSON path (`items[2].html`), in words an agent can act on. */
export interface BoardIssue { readonly path: string; readonly message: string }

/**
 * The outcome of reading a board. `newer` is a valid `board@N` with N above this module's version: the host should say so, not guess.
 * `invalid` covers bad JSON, a missing or unknown `format` (unversioned files are invalid), and every shape error.
 */
export type BoardParse =
  | { readonly kind: 'ok'; readonly board: Board }
  | { readonly kind: 'newer'; readonly format: string; readonly version: number }
  | { readonly kind: 'invalid'; readonly issues: readonly BoardIssue[] };

const MAX_ITEMS = 40, MAX_LINKS = 80, MAX_LAYOUT = 200, MAX_NOTE = 1000;
const ITEM_ID = /^[A-Za-z0-9][A-Za-z0-9_-]{0,59}$/;
/** Frame ids are `<item>/<screen>`, so layout keys may hold one slash. */
const FRAME_ID = /^[A-Za-z0-9][\w./-]{0,119}$/;
const COORDINATE = 1e6;
const FORMAT_LIKE = /^board@(.*)$/;

type Obj = Record<string, unknown>;
const isObject = (value: unknown): value is Obj => value !== null && typeof value === 'object' && !Array.isArray(value);

/** A workspace path relative to the board's folder, ending in `ending`: no scheme, no absolute path, no `..`. */
export function boardPathProblem(value: unknown, ending: '.maquette.json' | '.mockup.html'): string | undefined {
  if (typeof value !== 'string' || !value) return 'must be a non-empty path string';
  if (value.length > 200) return 'path is longer than 200 characters';
  if (/^[a-z]+:/i.test(value) || value.startsWith('/') || value.includes('\\')) return 'must be a relative path inside the board folder';
  if (value.split('/').includes('..')) return 'must not contain ".."';
  if (!value.toLowerCase().endsWith(ending)) return `must end with ${ending}`;
  return undefined;
}

function optionalText(value: unknown, path: string, max: number, issues: BoardIssue[]): string | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'string') { issues.push({ path, message: 'must be a string' }); return undefined; }
  if (value.length > max) issues.push({ path, message: `is longer than ${max} characters` });
  return value.slice(0, max);
}

function optionalNumber(value: unknown, path: string, min: number, max: number, issues: BoardIssue[]): number | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'number' || !Number.isFinite(value) || value < min || value > max) {
    issues.push({ path, message: `must be a number from ${min} to ${max}` });
    return undefined;
  }
  return value;
}

function unknownFields(value: Obj, allowed: readonly string[], path: string, issues: BoardIssue[]) {
  for (const key of Object.keys(value)) if (!allowed.includes(key)) issues.push({ path: path ? `${path}.${key}` : key, message: `unknown field (allowed: ${allowed.join(', ')})` });
}

function readItem(value: unknown, path: string, issues: BoardIssue[]): BoardItem | undefined {
  if (!isObject(value)) { issues.push({ path, message: 'must be an object' }); return undefined; }
  const id = value['id'];
  if (typeof id !== 'string' || !ITEM_ID.test(id)) { issues.push({ path: `${path}.id`, message: 'must be 1 to 60 letters, digits, "-" or "_", starting with a letter or digit' }); return undefined; }
  const kinds = ['maquette', 'html', 'note'].filter(kind => kind in value);
  if (kinds.length !== 1) { issues.push({ path, message: 'needs exactly one of "maquette", "html" or "note"' }); return undefined; }
  const kind = kinds[0];
  const title = optionalText(value['title'], `${path}.title`, 120, issues);
  if (kind === 'maquette') {
    unknownFields(value, ['id', 'maquette', 'title'], path, issues);
    const problem = boardPathProblem(value['maquette'], '.maquette.json');
    if (problem) { issues.push({ path: `${path}.maquette`, message: problem }); return undefined; }
    return { id, maquette: value['maquette'] as string, ...(title ? { title } : {}) };
  }
  if (kind === 'html') {
    unknownFields(value, ['id', 'html', 'title', 'device', 'width', 'height'], path, issues);
    const problem = boardPathProblem(value['html'], '.mockup.html');
    if (problem) { issues.push({ path: `${path}.html`, message: problem }); return undefined; }
    const device = value['device'] === undefined ? 'phone' : value['device'];
    if (device !== 'phone' && device !== 'desktop') { issues.push({ path: `${path}.device`, message: 'must be "phone" or "desktop"' }); return undefined; }
    const width = optionalNumber(value['width'], `${path}.width`, 240, 1600, issues);
    const height = optionalNumber(value['height'], `${path}.height`, 240, 2400, issues);
    return { id, html: value['html'] as string, device, ...(title ? { title } : {}), ...(width !== undefined ? { width } : {}), ...(height !== undefined ? { height } : {}) };
  }
  unknownFields(value, ['id', 'note', 'near'], path, issues);
  const note = value['note'];
  if (typeof note !== 'string' || !note.trim() || note.length > MAX_NOTE) { issues.push({ path: `${path}.note`, message: `must be 1 to ${MAX_NOTE} characters` }); return undefined; }
  const near = value['near'];
  if (near !== undefined && (typeof near !== 'string' || !FRAME_ID.test(near))) { issues.push({ path: `${path}.near`, message: 'must name a frame id, such as "booking/sessions"' }); return undefined; }
  return { id, note, ...(near !== undefined ? { near } : {}) };
}

function readLink(value: unknown, path: string, issues: BoardIssue[]): BoardLink | undefined {
  if (!isObject(value)) { issues.push({ path, message: 'must be an object' }); return undefined; }
  unknownFields(value, ['from', 'to', 'label'], path, issues);
  const from = value['from'], to = value['to'];
  for (const [field, end] of [['from', from], ['to', to]] as const) {
    if (typeof end !== 'string' || !FRAME_ID.test(end)) { issues.push({ path: `${path}.${field}`, message: 'must name a frame id, such as "booking/confirmed"' }); return undefined; }
  }
  const label = optionalText(value['label'], `${path}.label`, 80, issues);
  return { from: from as string, to: to as string, ...(label ? { label } : {}) };
}

/** Reads a board (its JSON text or an already parsed value). Never throws. */
export function parseBoard(input: unknown): BoardParse {
  let raw: unknown = input;
  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw); } catch { return { kind: 'invalid', issues: [{ path: '', message: 'is not valid JSON' }] }; }
  }
  if (!isObject(raw)) return { kind: 'invalid', issues: [{ path: '', message: 'must be a JSON object' }] };
  const format = raw['format'];
  if (format === undefined) return { kind: 'invalid', issues: [{ path: 'format', message: `is missing: an unversioned board is invalid, write "format": "${BOARD_FORMAT}"` }] };
  if (typeof format !== 'string') return { kind: 'invalid', issues: [{ path: 'format', message: `must be a string such as "${BOARD_FORMAT}"` }] };
  const versioned = FORMAT_LIKE.exec(format)?.[1];
  const version = versioned !== undefined && /^[1-9]\d{0,3}$/.test(versioned) ? Number(versioned) : undefined;
  if (version === undefined) return { kind: 'invalid', issues: [{ path: 'format', message: `is "${format.slice(0, 40)}", not a board format such as "${BOARD_FORMAT}"` }] };
  if (version > BOARD_FORMAT_VERSION) return { kind: 'newer', format, version };
  if (version !== BOARD_FORMAT_VERSION) return { kind: 'invalid', issues: [{ path: 'format', message: `"${format}" is not a known board version` }] };

  const issues: BoardIssue[] = [];
  unknownFields(raw, ['format', 'title', 'items', 'links', 'layout'], '', issues);
  const title = optionalText(raw['title'], 'title', 120, issues) ?? '';

  const items: BoardItem[] = [];
  const seen = new Set<string>();
  const list = raw['items'];
  if (!Array.isArray(list)) issues.push({ path: 'items', message: 'must be a list (use [] for an empty board)' });
  else if (list.length > MAX_ITEMS) issues.push({ path: 'items', message: `has ${list.length} items; at most ${MAX_ITEMS}` });
  else list.forEach((value, index) => {
    const item = readItem(value, `items[${index}]`, issues);
    if (!item) return;
    if (seen.has(item.id)) { issues.push({ path: `items[${index}].id`, message: `"${item.id}" is already used by another item` }); return; }
    seen.add(item.id);
    items.push(item);
  });

  const links: BoardLink[] = [];
  const linkList = raw['links'] ?? [];
  if (!Array.isArray(linkList)) issues.push({ path: 'links', message: 'must be a list' });
  else if (linkList.length > MAX_LINKS) issues.push({ path: 'links', message: `has ${linkList.length} links; at most ${MAX_LINKS}` });
  else linkList.forEach((value, index) => { const link = readLink(value, `links[${index}]`, issues); if (link) links.push(link); });

  const layout: Record<string, BoardPoint> = {};
  const layoutSpec = raw['layout'] ?? {};
  if (!isObject(layoutSpec)) issues.push({ path: 'layout', message: 'must be an object from frame or note id to {"x", "y"}' });
  else if (Object.keys(layoutSpec).length > MAX_LAYOUT) issues.push({ path: 'layout', message: `has more than ${MAX_LAYOUT} entries` });
  else for (const [id, value] of Object.entries(layoutSpec)) {
    const path = `layout.${id}`;
    if (!FRAME_ID.test(id)) { issues.push({ path, message: 'is not a frame or note id' }); continue; }
    if (!isObject(value)) { issues.push({ path, message: 'must be {"x": number, "y": number}' }); continue; }
    const x = optionalNumber(value['x'], `${path}.x`, -COORDINATE, COORDINATE, issues);
    const y = optionalNumber(value['y'], `${path}.y`, -COORDINATE, COORDINATE, issues);
    if (x !== undefined && y !== undefined) layout[id] = { x, y };
  }

  if (issues.length) return { kind: 'invalid', issues };
  return { kind: 'ok', board: { format: BOARD_FORMAT, title, items, links, layout } };
}

/** What a canvas draws. Ids are stable: `<item>/<screen>` for maquette frames, the item id for HTML frames and notes. */
export interface PlannedFrame { readonly id: string; readonly kind: 'maquette' | 'html'; readonly src: string; readonly screen: string; readonly title: string; readonly x: number; readonly y: number; readonly w: number; readonly h: number }
export interface PlannedArrow { readonly id: string; readonly from: string; readonly to: string; readonly label: string }
export interface PlannedNote { readonly id: string; readonly text: string; readonly x: number; readonly y: number }
export interface BoardPlan {
  readonly frames: readonly PlannedFrame[];
  readonly arrows: readonly PlannedArrow[];
  readonly notes: readonly PlannedNote[];
  /** Referenced files that are missing or unreadable, and links that name no frame. The plan still draws everything else. */
  readonly problems: readonly BoardIssue[];
}

const SIZE = { phone: { w: 390, h: 780 }, desktop: { w: 1024, h: 720 } } as const;
const GAP = 160;

/**
 * Lays the board out left to right. `files` maps each referenced path to its text: a maquette is needed for its screens and goto links.
 * A frame with a layout entry keeps that position; the automatic frames go to the right of everything placed before them.
 */
export function planBoard(board: Board, files: ReadonlyMap<string, string>): BoardPlan {
  const frames: PlannedFrame[] = [], notes: PlannedNote[] = [], problems: BoardIssue[] = [];
  const maquettes = new Map<string, Maquette>();
  const arrowLinks: { from: string; to: string; label: string; source: string }[] = [];
  let cursor = 0;
  // Automatic frames go to the right of everything placed so far, so a frame a person moved never overlaps one the layout did not place.
  const place = (id: string, w: number): BoardPoint => {
    const at = board.layout[id] ?? { x: cursor, y: 0 };
    cursor = Math.max(cursor, at.x + w + GAP);
    return at;
  };

  for (const item of board.items) {
    if ('maquette' in item) {
      const text = files.get(item.maquette);
      const parsed = text === undefined ? undefined : parseMaquette(text);
      if (!parsed || parsed.kind !== 'ok') {
        problems.push({ path: `items.${item.id}`, message: text === undefined ? `${item.maquette} is missing` : `${item.maquette} is not a readable maquette` });
        continue;
      }
      const maquette = parsed.maquette;
      maquettes.set(item.id, maquette);
      const size = SIZE[maquette.device === 'desktop' ? 'desktop' : 'phone'];
      for (const screen of maquette.screens) {
        const id = `${item.id}/${screen.id}`;
        const at = place(id, size.w);
        frames.push({ id, kind: 'maquette', src: item.maquette, screen: screen.id, title: screen.title, x: at.x, y: at.y, ...size });
      }
      for (const screen of maquette.screens) for (const target of linksOf(screen.blocks))
        arrowLinks.push({ from: `${item.id}/${screen.id}`, to: `${item.id}/${target}`, label: '', source: `${item.id}/${screen.id}` });
    } else if ('html' in item) {
      const device = SIZE[item.device];
      const size = { w: item.width ?? device.w, h: item.height ?? device.h };
      const at = place(item.id, size.w);
      frames.push({ id: item.id, kind: 'html', src: item.html, screen: '', title: item.title ?? item.html, x: at.x, y: at.y, ...size });
      if (!files.has(item.html)) problems.push({ path: `items.${item.id}`, message: `${item.html} is missing` });
    }
  }

  const frameIds = new Set(frames.map(frame => frame.id));
  for (const link of board.links) arrowLinks.push({ from: link.from, to: link.to, label: link.label ?? '', source: `links.${link.from}->${link.to}` });
  const arrows: PlannedArrow[] = [];
  for (const link of arrowLinks) {
    if (frameIds.has(link.from) && frameIds.has(link.to)) arrows.push({ id: `${link.from}->${link.to}`, from: link.from, to: link.to, label: link.label });
    else problems.push({ path: link.source, message: `${frameIds.has(link.from) ? link.to : link.from} is not a frame on this board` });
  }

  for (const item of board.items) if ('note' in item) {
    const near = item.near === undefined ? undefined : frames.find(frame => frame.id === item.near);
    if (item.near !== undefined && !near) problems.push({ path: `items.${item.id}.near`, message: `${item.near} is not a frame on this board` });
    const at = board.layout[item.id] ?? (near ? { x: near.x + near.w - 120, y: near.y - 260 } : { x: cursor, y: 0 });
    notes.push({ id: item.id, text: item.note, x: at.x, y: at.y });
  }
  return { frames, arrows, notes, problems };
}

/** Frame and note positions, and the notes after people edited them on the canvas. */
export interface CanvasEdits {
  readonly positions: Readonly<Record<string, BoardPoint>>;
  /** Every note that remains. A note missing here was deleted. Its `near` is kept from the board. */
  readonly notes: readonly { readonly id: string; readonly text: string }[];
}

export type BoardEditResult = { readonly kind: 'ok'; readonly board: Board } | { readonly kind: 'invalid'; readonly issues: readonly BoardIssue[] };

/**
 * Writes people's canvas edits back into a board, as `board@1`: `layout` takes the new positions and the note items take the notes.
 * Maquette, HTML and link entries are never changed. The result is valid by construction and is checked as if it were read from a file.
 */
export function applyCanvasEdits(board: Board, edits: CanvasEdits): BoardEditResult {
  const issues: BoardIssue[] = [];
  const kept = board.items.filter(item => !('note' in item));
  const keptIds = new Set(kept.map(item => item.id));
  const near = new Map(board.items.flatMap(item => 'note' in item ? [[item.id, item.near] as const] : []));
  const notes: BoardItem[] = [];
  edits.notes.forEach((note, index) => {
    if (!ITEM_ID.test(note.id) || keptIds.has(note.id)) { issues.push({ path: `notes[${index}].id`, message: `"${note.id}" is not a free note id` }); return; }
    const text = note.text.trim();
    if (!text) { issues.push({ path: `notes[${index}].text`, message: 'is empty' }); return; }
    const attached = near.get(note.id);
    notes.push({ id: note.id, note: text.slice(0, MAX_NOTE), ...(attached !== undefined ? { near: attached } : {}) });
  });
  const layout: Record<string, BoardPoint> = {};
  for (const [id, at] of Object.entries(edits.positions)) {
    if (!FRAME_ID.test(id)) { issues.push({ path: `positions.${id}`, message: 'is not a frame or note id' }); continue; }
    if (!Number.isFinite(at.x) || !Number.isFinite(at.y) || Math.abs(at.x) > COORDINATE || Math.abs(at.y) > COORDINATE) { issues.push({ path: `positions.${id}`, message: 'is not a finite position' }); continue; }
    layout[id] = { x: Math.round(at.x), y: Math.round(at.y) };
  }
  if (Object.keys(layout).length > MAX_LAYOUT) issues.push({ path: 'positions', message: `has more than ${MAX_LAYOUT} entries` });
  if (kept.length + notes.length > MAX_ITEMS) issues.push({ path: 'notes', message: `would make more than ${MAX_ITEMS} items` });
  if (issues.length) return { kind: 'invalid', issues };
  return { kind: 'ok', board: { ...board, items: [...kept, ...notes], layout } };
}

/** The board's file text: `board@1` JSON, two-space indented, with a trailing newline. */
export const serializeBoard = (board: Board): string => `${JSON.stringify(board, null, 2)}\n`;

'use client';

import { lazy, Suspense, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import type { ResourceLocator } from '@hachej/boring-files';
import { createTextBuffer } from '@hachej/boring-ui-kit/text-buffer';
import type { TextBuffer } from '@hachej/boring-ui-kit/text-buffer';
import { Button } from '@/components/ui/button';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import type { BoardHostProps, BoardViewerProps } from './board-props';
export type { BoardHostProps, BoardViewerProps } from './board-props';
import { parseBoard } from './board';

export { parseBoard, planBoard, applyCanvasEdits, serializeBoard } from './board';
export type { Board, BoardPlan } from './board';
const Canvas = lazy(() => import('./board-canvas'));

const readText = (snapshot: Parameters<Parameters<typeof createTextBuffer>[0]['readText']>[0]) => {
  const text = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(snapshot.bytes);
  if (parseBoard(text).kind !== 'ok') throw new Error('Unreadable board');
  return text;
};

export function BoardViewer(props: BoardViewerProps) {
  const parsed = useMemo(() => parseBoard(props.text), [props.text]);
  if (parsed.kind !== 'ok') return <Alert role="alert"><AlertTitle>{parsed.kind === 'newer' ? 'Newer board format' : 'This board cannot be read'}</AlertTitle>
    <AlertDescription>{parsed.kind === 'newer' ? parsed.format : parsed.issues.map(issue => `${issue.path}: ${issue.message}`).join('; ')}</AlertDescription></Alert>;
  const key = JSON.stringify([props.target, props.identity, props.pinned]);
  return <BoardSession key={key} {...props} />;
}

function BoardSession({ text, revision, target, pinned, client, identity, ...host }: BoardViewerProps) {
  const [buffer, setBuffer] = useState<TextBuffer>();
  // A changed revision refreshes the existing buffer below; it must not replace a dirty canvas. A new buffer starts from the latest text.
  const saved = useRef({ text, revision });
  useLayoutEffect(() => { saved.current = { text, revision }; });
  useEffect(() => {
    const { text, revision } = saved.current;
    const next = createTextBuffer({ client, identity, instanceId: 'board', epoch: revision, readOnly: pinned || !client.publish,
      source: { kind: 'saved', snapshot: { ref: { ...target, revision }, bytes: new TextEncoder().encode(text), mediaType: 'application/json' } },
      mediaType: 'application/json', readText });
    setBuffer(next);
    return () => next.dispose();
  }, [client, identity, target, pinned]);
  useEffect(() => {
    if (!buffer || pinned) return;
    const state = buffer.getSnapshot();
    if (state.base.kind === 'revision' && state.base.target.revision !== revision) void buffer.refresh(false);
  }, [buffer, text, revision, pinned]);
  return buffer ? <BoardDocument {...host} buffer={buffer} client={client} target={target} pinned={pinned} /> : <p role="status">Loading board…</p>;
}

function BoardDocument({ buffer, client, target, pinned, ...host }: Omit<BoardHostProps, 'identity'> & { readonly buffer: TextBuffer; readonly target: ResourceLocator; readonly pinned: boolean }) {
  const state = useSyncExternalStore(buffer.subscribe, buffer.getSnapshot, buffer.getSnapshot);
  const parsed = useMemo(() => parseBoard(state.text), [state.text]);
  // Layout-only edits must not fetch linked files or remount the projection.
  const sources = parsed.kind === 'ok' ? JSON.stringify([...new Set(parsed.board.items.flatMap(item => 'maquette' in item ? [item.maquette] : 'html' in item ? [item.html] : []))]) : '[]';
  const [loaded, setLoaded] = useState<{ readonly sources: string; readonly files: ReadonlyMap<string, string> }>();
  const [error, setError] = useState<string>();
  useEffect(() => {
    let live = true;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- a new read (client, target or sources) clears the previous read's error once; the effect then reads asynchronously
    setError(undefined);
    const paths: string[] = JSON.parse(sources);
    const folder = target.resource.path.slice(0, target.resource.path.lastIndexOf('/') + 1);
    void Promise.all(paths.map(async relative => {
      const result = await client.read({ target: { ...target, resource: { ...target.resource, path: folder + relative } }, revision: { kind: 'latest' } });
      if (result.kind !== 'available') throw new Error('Linked files are unavailable');
      return [relative, new TextDecoder('utf-8', { fatal: true, ignoreBOM: true }).decode(result.snapshot.bytes)] as const;
    })).then(entries => { if (live) setLoaded({ sources, files: new Map(entries) }); }, () => { if (live) setError('Linked files are unavailable. Reload the board to retry.'); });
    return () => { live = false; };
  }, [client, target, sources]);
  const outcome = state.save.kind === 'settled' ? state.save.result : undefined;
  const conflict = state.remote !== null || outcome?.kind === 'conflict';
  const unknown = outcome?.kind === 'unknown';
  const pending = state.save.kind === 'pending';
  const run = (action: () => Promise<unknown>) => { void action().catch(() => setError('Board operation failed. Your local edits are retained.')); };
  return <section className="flex h-full min-h-0 flex-col" data-boring="board-viewer">
    <div role="status" data-testid="board-save" className="text-muted-foreground">{pinned ? 'Read only' : pending ? 'Saving…' : unknown ? 'Save unconfirmed' : conflict ? 'Changed elsewhere' : outcome && outcome.kind !== 'saved' ? 'Save failed' : state.dirty ? 'Unsaved changes' : 'Saved'}</div>
    {conflict && <Alert role="alert" data-testid="board-conflict"><AlertTitle>Changed elsewhere</AlertTitle><AlertDescription>Your local edits have been kept.</AlertDescription>
      <Button disabled={pending || unknown} onClick={() => run(() => buffer.refresh(true))}>Discard local changes and reload</Button></Alert>}
    {unknown && <Alert role="alert"><AlertTitle>Save unconfirmed</AlertTitle><AlertDescription>Your local edits have been kept. Do not repeat the save.</AlertDescription>
      <Button onClick={() => run(buffer.reconcile)}>Check save outcome</Button><Button onClick={() => run(buffer.abandon)}>Keep draft and refresh</Button></Alert>}
    {error && <Alert role="alert"><AlertTitle>{error}</AlertTitle></Alert>}
    {!error && loaded?.sources === sources && parsed.kind === 'ok' && <Suspense fallback={<p role="status">Loading board…</p>}>
      <Canvas {...host} buffer={buffer} files={loaded.files} />
    </Suspense>}
  </section>;
}

'use client';

// Ported from spike/canvas-board. Native shapes are a disposable projection of board@1, never a saved tldraw store.
import { createContext, useCallback, useContext, useEffect, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react';
import { HTMLContainer, Rectangle2d, ShapeUtil, T, createShapeId, renderPlaintextFromRichText, toRichText, useValue } from 'tldraw';
import type { Editor, TLBaseShape } from 'tldraw';
import { CanvasProjection } from '@hachej/boring-ui-kit/canvas-editor';
import type { TextBuffer } from '@hachej/boring-ui-kit/text-buffer';
import { HandIcon, MousePointer2Icon, StickyNoteIcon, MaximizeIcon, Undo2Icon, Redo2Icon, MessageSquarePlusIcon } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Tooltip, TooltipContent, TooltipTrigger } from '@/components/ui/tooltip';
import { MockupViewer } from '../mockup-viewer/mockup-viewer';
import { parseMaquette } from '../maquette-viewer/maquette';
import { MaquetteScreenView } from '../maquette-viewer/maquette-blocks';
import { defaultMaquetteLabels } from '../maquette-viewer/maquette-labels';
import { applyCanvasEdits, parseBoard, planBoard, serializeBoard } from './board';
import type { Board } from './board';
import type { BoardHostProps } from './board-props';

const FRAME = 'board-frame';
type FrameProps = { w: number; h: number; kind: string; src: string; screen: string; title: string; frameId: string };
type BoardFrame = TLBaseShape<typeof FRAME, FrameProps>;
declare module 'tldraw' { interface TLGlobalShapePropsMap { 'board-frame': FrameProps } }
interface BoardContext {
  readonly files: ReadonlyMap<string, string>;
  readonly comments: BoardHostProps['comments'];
  readonly path: string;
  readonly go: (frameId: string, screen: string) => void;
}
const Context = createContext<BoardContext>({ files: new Map(), comments: undefined, path: '', go: () => {} });
const frameId = (id: string) => createShapeId(`frame-${id}`);

function FrameContent({ shape, editor }: { readonly shape: BoardFrame; readonly editor: Editor }) {
  const board = useContext(Context);
  const editing = useValue('board frame editing', () => editor.getEditingShapeId() === shape.id, [editor, shape.id]);
  const { src, kind, screen, frameId: id, title } = shape.props;
  const text = board.files.get(src) ?? '';
  const parsed = useMemo(() => kind === 'maquette' ? parseMaquette(text) : undefined, [kind, text]);
  const shown = parsed?.kind === 'ok' ? parsed.maquette.screens.find(item => item.id === screen) : undefined;
  return <HTMLContainer className="flex flex-col" style={{ width: shape.props.w, height: shape.props.h }}>
    <div className="pointer-events-none absolute -top-8 left-0 whitespace-nowrap text-muted-foreground" data-testid="board-frame-title">{title}</div>
    <Card className="min-h-0 flex-1 overflow-hidden" data-testid="board-frame" data-frame={id}>
      <CardContent className="min-h-0 flex-1 overflow-hidden" style={{ pointerEvents: editing || board.comments?.active ? 'auto' : 'none' }}>
        {kind === 'html' ? <MockupViewer text={text} path={src} comments={board.comments} />
          : shown && parsed?.kind === 'ok' ? <MaquetteScreenView maquette={parsed.maquette} screen={shown} labels={defaultMaquetteLabels}
            links={{ go: target => board.go(id, target), hint: target => `Opens ${target}`,
              target: block => `board:${board.path}#frame=${id}&block=${block.id}`,
              pins: block => board.comments?.pins.filter(pin => pin.target === `board:${board.path}#frame=${id}&block=${block.id}`).map(pin => pin.number) ?? [] }}  /> : <p role="alert">Unreadable maquette {src}</p>}
      </CardContent>
    </Card>
  </HTMLContainer>;
}

class BoardFrameUtil extends ShapeUtil<BoardFrame> {
  static override type = FRAME;
  static override props = { w: T.number, h: T.number, kind: T.string, src: T.string, screen: T.string, title: T.string, frameId: T.string };
  override getDefaultProps(): FrameProps { return { w: 390, h: 780, kind: 'maquette', src: '', screen: '', title: '', frameId: '' }; }
  override canEdit() { return !this.editor.getIsReadonly(); }
  override canResize() { return false; }
  override canBind() { return true; }
  override hideRotateHandle() { return true; }
  override getGeometry(shape: BoardFrame) { return new Rectangle2d({ width: shape.props.w, height: shape.props.h, isFilled: true }); }
  override component(shape: BoardFrame) { return <FrameContent shape={shape} editor={this.editor} />; }
  override getIndicatorPath(shape: BoardFrame) { const path = new Path2D(); path.rect(0, 0, shape.props.w, shape.props.h); return path; }
}
const shapeUtils = [BoardFrameUtil];

function project(editor: Editor, board: Board, files: ReadonlyMap<string, string>) {
  const plan = planBoard(board, files);
  const readOnly = editor.getIsReadonly();
  editor.updateInstanceState({ isReadonly: false });
  try { editor.store.mergeRemoteChanges(() => editor.run(() => {
    editor.deleteShapes([...editor.getCurrentPageShapeIds()]);
    editor.createShapes<BoardFrame>(plan.frames.map(frame => ({ id: frameId(frame.id), type: FRAME, x: frame.x, y: frame.y,
      props: { w: frame.w, h: frame.h, kind: frame.kind, src: frame.src, screen: frame.screen, title: frame.title, frameId: frame.id } })));
    const at = new Map(plan.frames.map(frame => [frame.id, frame]));
    // Duplicate goto targets produce one arrow per pair.
    for (const arrow of new Map(plan.arrows.map(arrow => [arrow.id, arrow])).values()) {
      const id = createShapeId(`arrow-${arrow.id}`);
      const backward = (at.get(arrow.from)?.x ?? 0) > (at.get(arrow.to)?.x ?? 0);
      editor.createShape({ id, type: 'arrow', isLocked: true, props: { start: { x: 0, y: 0 }, end: { x: 1, y: 0 }, bend: backward ? -260 : 0,
        richText: toRichText(arrow.label), dash: backward ? 'dashed' : 'solid' } });
      editor.createBindings(([['start', arrow.from], ['end', arrow.to]] as const).map(([terminal, frame]) => ({ type: 'arrow', fromId: id, toId: frameId(frame),
        props: { terminal, normalizedAnchor: { x: 0.5, y: 0.5 }, isExact: false, isPrecise: false, snap: 'none' } })));
    }
    editor.createShapes(plan.notes.map(note => ({ id: createShapeId(`note-${note.id}`), type: 'note', x: note.x, y: note.y, props: { richText: toRichText(note.text) } })));
  }, { history: 'ignore', ignoreShapeLock: true })); }
  finally { editor.updateInstanceState({ isReadonly: readOnly }); }
  return plan;
}

function capture(editor: Editor, board: Board): Board | undefined {
  const positions: Record<string, { x: number; y: number }> = {};
  const notes: { id: string; text: string }[] = [];
  for (const shape of editor.getCurrentPageShapes()) {
    if (editor.isShapeOfType<BoardFrame>(shape, FRAME)) positions[shape.props.frameId] = { x: shape.x, y: shape.y };
    if (editor.isShapeOfType(shape, 'note')) {
      const id = shape.id.startsWith('shape:note-') ? shape.id.slice('shape:note-'.length) : `note-${shape.id.slice(6)}`;
      positions[id] = { x: shape.x, y: shape.y };
      notes.push({ id, text: renderPlaintextFromRichText(editor, shape.props.richText) });
    }
  }
  const result = applyCanvasEdits(board, { positions, notes });
  return result.kind === 'ok' ? result.board : undefined;
}

export default function BoardCanvas({ buffer, files, assetUrls, licenseKey, onEditor, comments }: Omit<BoardHostProps, 'identity' | 'client'> & { readonly buffer: TextBuffer; readonly files: ReadonlyMap<string, string> }) {
  const state = useSyncExternalStore(buffer.subscribe, buffer.getSnapshot, buffer.getSnapshot);
  const [phone, setPhone] = useState(() => typeof matchMedia === 'function' && matchMedia('(max-width: 639px), (pointer: coarse)').matches);
  useEffect(() => {
    const media = matchMedia('(max-width: 639px), (pointer: coarse)');
    const changed = () => setPhone(media.matches);
    media.addEventListener('change', changed);
    return () => media.removeEventListener('change', changed);
  }, []);
  const editorRef = useRef<Editor | null>(null);
  const projected = useRef(state.text);
  const [editor, setEditor] = useState<Editor | null>(null);
  const blocked = state.readOnly || phone;
  const mode = useRef(blocked);
  useLayoutEffect(() => { mode.current = blocked; });
  const [problem, setProblem] = useState<string>();
  const attach = useCallback((native: Editor) => {
    editorRef.current = native;
    const parsed = parseBoard(buffer.getSnapshot().text);
    if (parsed.kind !== 'ok') return;
    projected.current = buffer.getSnapshot().text;
    const plan = project(native, parsed.board, files);
    native.updateInstanceState({ isReadonly: mode.current });
    native.setCurrentTool(mode.current ? 'hand' : 'select');
    const fit = () => {
      native.updateViewportScreenBounds(native.getContainer());
      const first = plan.frames[0] && native.getShapePageBounds(frameId(plan.frames[0].id));
      if (mode.current && first) native.zoomToBounds(first, { animation: { duration: 0 }, inset: 24 });
      else native.zoomToFit({ animation: { duration: 0 } });
    };
    fit();
    const timer = setTimeout(fit, 400);
    // Frame identity/content and goto arrows come only from board@1, never native delete/paste/rotate operations.
    const stopDelete = native.sideEffects.registerBeforeDeleteHandler('shape', (shape, source) => { if (source === 'user' && (shape.type === FRAME || shape.type === 'arrow')) return false; });
    const stopUpdate = native.sideEffects.registerBeforeChangeHandler('shape', (previous, next, source) => source === 'user' && previous.type === FRAME ? { ...previous, x: next.x, y: next.y } : next);
    const stop = native.store.listen(() => {
      if (mode.current) return;
      const current = parseBoard(buffer.getSnapshot().text);
      if (current.kind !== 'ok') return;
      const next = capture(native, current.board);
      if (!next) { setProblem('Finish the note before saving.'); return; }
      setProblem(undefined);
      projected.current = serializeBoard(next);
      buffer.edit(projected.current);
    }, { source: 'user', scope: 'document' });
    setEditor(native); onEditor?.(native);
    return () => { clearTimeout(timer); stop(); stopDelete(); stopUpdate(); editorRef.current = null; setEditor(null); onEditor?.(null); };
  }, [buffer, files, onEditor]);
  useEffect(() => {
    if (!editor) return;
    editor.updateInstanceState({ isReadonly: blocked });
    if (blocked) editor.setCurrentTool('hand');
  }, [editor, blocked]);
  useEffect(() => {
    if (!editor || state.text === projected.current) return;
    const parsed = parseBoard(state.text);
    if (parsed.kind === 'ok') { project(editor, parsed.board, files); projected.current = state.text; }
  }, [editor, state.text, files]);
  useEffect(() => {
    if (blocked || problem || !state.dirty || state.remote || state.save.kind === 'pending' || state.save.kind === 'settled' && state.save.result.kind !== 'saved') return;
    const timer = setTimeout(() => { void buffer.flush(buffer.selection()); }, 600);
    return () => clearTimeout(timer);
  }, [buffer, state, blocked, problem]);
  const context = useMemo<BoardContext>(() => ({ files, comments, path: state.base.target.resource.path, go: (id, screen) => {
    const native = editorRef.current;
    const target = native?.getShape(frameId(`${id.split('/')[0]}/${screen}`));
    const bounds = target && native?.getShapePageBounds(target);
    if (native && bounds) native.zoomToBounds(bounds, { animation: { duration: 200 }, inset: 24 });
  } }), [files, comments, state.base.target.resource.path]);
  return <Context.Provider value={context}><div data-testid="board" data-phone={phone} className="relative min-h-0 flex-1 overscroll-contain" style={{ touchAction: 'none' }}>
    <CanvasProjection assetUrls={assetUrls} licenseKey={licenseKey} hideUi shapeUtils={shapeUtils} onMount={attach} />
    {editor && <BoardTools editor={editor} blocked={blocked} comments={comments} />}
    {problem && <p role="alert" className="absolute bottom-2 left-2 text-muted-foreground">{problem}</p>}
  </div></Context.Provider>;
}

function BoardTools({ editor, blocked, comments }: { readonly editor: Editor; readonly blocked: boolean; readonly comments: BoardHostProps['comments'] }) {
  const native = useValue('board toolbar', () => ({ undo: editor.getCanUndo(), redo: editor.getCanRedo() }), [editor]);
  const tools = [
    ...(!blocked ? [{ label: 'Select frames', icon: MousePointer2Icon, action: () => editor.setCurrentTool('select') }, { label: 'Pan board', icon: HandIcon, action: () => editor.setCurrentTool('hand') },
      { label: 'Add note', icon: StickyNoteIcon, action: () => editor.setCurrentTool('note') }, { label: 'Undo', icon: Undo2Icon, action: () => editor.undo(), disabled: !native.undo },
      { label: 'Redo', icon: Redo2Icon, action: () => editor.redo(), disabled: !native.redo }] : []),
    { label: 'Fit board', icon: MaximizeIcon, action: () => editor.zoomToFit() },
    ...(comments ? [{ label: 'Comment on board', icon: MessageSquarePlusIcon, action: comments.point }] : []),
  ];
  return <nav aria-label="Board tools" data-feedback-ignore="" className="absolute top-2 left-2 z-[300] flex flex-wrap gap-1">
    {tools.map(tool => <Tooltip key={tool.label}><TooltipTrigger render={<Button size="icon" aria-label={tool.label} disabled={'disabled' in tool && tool.disabled} onClick={tool.action} />}><tool.icon aria-hidden="true" /></TooltipTrigger><TooltipContent>{tool.label}</TooltipContent></Tooltip>)}
  </nav>;
}

import type { ResourceClient, ResourceLocator } from '@hachej/boring-files';
import type { TextBufferState } from '@hachej/boring-ui-kit/text-buffer';
import type { CanvasAssetUrls } from '@hachej/boring-ui-kit/canvas-editor';
import type { Editor } from 'tldraw';
import type { MockupComments } from '../mockup-viewer/mockup-viewer';

export interface BoardHostProps {
  readonly client: ResourceClient;
  readonly identity: TextBufferState['identity'];
  readonly assetUrls: CanvasAssetUrls;
  readonly licenseKey?: string | undefined;
  /** Existing host point-comments binding; structured board pin delivery is installed separately. */
  readonly comments?: MockupComments | undefined;
  /** The editor and its store are a disposable projection, never the saved document. */
  readonly onEditor?: ((editor: Editor | null) => void) | undefined;
}
export interface BoardViewerProps extends BoardHostProps {
  readonly target: ResourceLocator;
  readonly text: string;
  readonly revision: string;
  readonly pinned: boolean;
}

'use client';

import { lazy } from 'react';
import { LayoutDashboardIcon } from 'lucide-react';
import type { ArtifactKind } from '../pi-artifacts/artifact';
import type { BoardHostProps } from './board-props';

const BoardViewer = lazy(() => import('./board-viewer').then(module => ({ default: module.BoardViewer })));

/** An opt-in artifact kind. Its client and authenticated receipt identity belong to the host's selected workspace. The viewer loads on first open. */
export function createBoardKind(host: BoardHostProps): ArtifactKind {
  return { match: target => /\.board\.json$/i.test(target.resource.path), label: 'Board', icon: LayoutDashboardIcon,
    renderer: ({ artifact, text, revision, pinned }) => <BoardViewer {...host} target={artifact.target} text={text} revision={revision} pinned={pinned} /> };
}
